import{_ as a,o as r,c as t,a5 as i}from"./chunks/framework.CXvGqWf0.js";const m=JSON.parse('{"title":"漫画 · 第 46 话 Service Worker 缓存策略：Cache First / Network First / SWR","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.46-service-worker-cache.md","filePath":"comics/html/EP.46-service-worker-cache.md","lastUpdated":1793421609000}'),o={name:"comics/html/EP.46-service-worker-cache.md"};function c(l,e,h,s,n,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="漫画-·-第-46-话-service-worker-缓存策略-cache-first-network-first-swr" tabindex="-1">漫画 · 第 46 话 Service Worker 缓存策略：Cache First / Network First / SWR <a class="header-anchor" href="#漫画-·-第-46-话-service-worker-缓存策略-cache-first-network-first-swr" aria-label="Permalink to &quot;漫画 · 第 46 话 Service Worker 缓存策略：Cache First / Network First / SWR&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/17-service-worker-cache">docs/html/17-service-worker-cache.md</a> ｜ 原画：<a href="./EP.46-service-worker-cache.svg">EP.46-service-worker-cache.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。用户抱怨地铁上打不开页面、电梯里白屏 30 秒、二次访问还慢——HTTP Cache-Control 太粗，无法按 URL 定制策略，离线等于完全不可用。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 Service Worker 三大缓存策略——Cache First 静态资源、Network First API、Stale While Revalidate 列表，让应用离线可用、秒开。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>用户对加载速度的忍耐是零。地铁、电梯、弱网环境打不开，竞争对手秒开，用户流失 30%。标签君用 Service Worker 拦截网络请求，按资源类型定制缓存策略：静态资源 Cache First 秒开、API Network First 实时优先、列表 SWR 秒开+后台更新。最后 CACHE_NAME 带版本号，activate 清理旧缓存，用户永远拿新版。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>用户抱怨：地铁上打不开、电梯里白屏 30 秒、二次访问还慢。HTTP Cache-Control 太粗，无法按 URL 定制策略；离线 = 完全不可用；竞争对手秒开，用户流失严重。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三大缓存策略：Cache First（有缓存用缓存，适用 CSS/JS/图片）；Network First（先走网络，失败用缓存，适用 API）；Stale While Revalidate（先返回缓存秒开，后台更新，适用新闻/商品列表）。SW 生命周期：install 预缓存 → activate 清理旧版 → fetch 拦截请求。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：静态资源 Cache First（二次访问秒开、服务器流量降 60%）、API Network First（实时优先、失败兜底）、列表 SWR（秒开+后台更新、体验最佳）、离线可用 PWA（地铁/电梯也能开）。Chrome 40+ / Safari 11.1+ / Firefox 44+ 全绿。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>Cache First 静态资源；Network First API；SWR 列表——别用错场景。</li><li>CACHE_NAME 必须带版本号，activate 清理旧缓存，否则用户永远拿旧版。</li><li>POST 请求不可缓存；带鉴权的 API 别缓存，换账号会串数据。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 CACHE_NAME 必须带版本号（如 <code>app-v1.2.3</code>），而不是固定 <code>app-cache</code>？</p><p><strong>答</strong>：SW 的 activate 事件里要清理旧缓存（<code>caches.delete(oldName)</code>）。如果 CACHE_NAME 固定，新版 SW 激活时无法区分新旧缓存，会误删当前版本，导致用户拿到旧资源或缓存失效。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>注册 SW + 三大缓存策略对比 + 缓存版本管理：<a href="./../../examples/html/17-service-worker-cache/index-01-service-worker-cache.html">examples/html/17-service-worker-cache/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 47 话《逻辑属性进阶》——margin-left/right 在 RTL 语言下全错？inline-start/block-end 让布局自动适配书写方向，国际化不再写两套样式。</p>',22)])])}const p=a(o,[["render",c]]);export{m as __pageData,p as default};
